 const jumpTo=(idx)=>{const g=new Chess();try{g.loadPgn(lesson?.moves||'')}catch{};const hs=g.history({verbose:true});const position=new Chess();hs.slice(0,idx).forEach(m=>position.move(m.san));setPosition(position,hs,idx)};
 const playMove=(from,to,promotion='q')=>{const g=new Chess(game.fen());try{const result=g.move({from,to,promotion});if(!result)return false;if(trainer){const expected=trainer.moves[trainer.index];if(!expected||result.san!==expected.san){setToast(`Not quite. The expected move is ${expected?.san||'the end of the line'}. Try again.`);return false}let nextIndex=trainer.index+1;if(nextIndex<trainer.moves.length&&trainer.moves[nextIndex].color===g.turn()){g.move(trainer.moves[nextIndex].san);nextIndex++}setPosition(g,trainer.moves,nextIndex);if(nextIndex>=trainer.moves.length){setTrainer(null);setToast('Line complete. Added to your review history.')}else{setTrainer({...trainer,index:nextIndex});setToast('Correct. Continue the line.')}return true}setPosition(g,[...moves,result],moveAt+1);return true}catch{return false}};
