 {view==='store'&&<><section className="store-hero"><div className="hero-copy"><div className="eyebrow-blue">THE CHESSBOARD PRESS · INTERACTIVE CHESS BOOKS</div><h1>Learn the game.<br/><em>One idea at a time.</em></h1><p>Expert instruction, brought to life on the board. Learn a move, understand the idea, make it your own.</p><button className="blue-button" onClick={()=>document.getElementById('catalog')?.scrollIntoView({behavior:'smooth'})}>Explore all courses <ArrowRight size={16}/></button><div className="hero-proof"><span>Interactive chess books</span><i/> Study by playing each line</div></div><div className="hero-feature"><div className={`featured-book-cover ${featured.cover}`}><span>CHESSBOARD PRESS <small>OPENING SERIES · 01</small></span><b>♞</b><i>THE<br/>VIENNA</i></div><div className="featured-caption"><span>FEATURED COURSE</span><b>{featured.title}</b><small>IM Levy Rozman · 3 chapters</small><button onClick={()=>{setActiveId(featured.id);go('product')}}>Explore book <ArrowRight size={14}/></button></div></div><div className="hero-index">01 <i/> 06</div></section><section className="catalog-area" id="catalog"><div className="catalog-heading"><div><small>DEMO COURSE CATALOGUE</small><h2>Find your next course</h2></div><label className="catalog-search"><Search size={16}/><input placeholder="Title, author, or topic" value={query} onChange={e=>setQuery(e.target.value)}/></label></div><div className="category-tabs">{categories.map(c=><button className={category===c?'active':''} key={c} onClick={()=>setCategory(c)}>{c}</button>)}</div><div className="shelf-heading"><h3>{category==='All'?'Best sellers':`${category} courses`}</h3><button onClick={()=>setCategory('All')}>View all <ArrowRight size={14}/></button></div><div className="products-grid">{listing.slice(0,4).map(b=>bookCard(b))}</div><div className="store-shelves"><section><div className="shelf-heading"><h3>New to the library</h3><button>Recently released <ArrowRight size={14}/></button></div><div className="products-grid">{books.filter(b=>b.status!=='draft').slice().reverse().slice(0,3).map(b=>bookCard(b))}</div></section><div className="store-callout"><div><span>LEARN WITH A PLAN</span><h3>Bring your opening<br/>repertoire to life.</h3><p>Follow structured lines and build recall with spaced review.</p><button onClick={()=>go('library')}>Go to my library <ArrowRight size={14}/></button></div><span className="callout-knight">♞</span></div></div><div className="topic-shelf"><div className="shelf-heading"><h3>Explore by discipline</h3><span>Find a focus for your next study session</span></div><div className="topic-list">{['Openings','Tactics','Middlegame','Endgames'].map((x,i)=><button key={x} onClick={()=>{setCategory(x);document.getElementById('catalog')?.scrollIntoView({behavior:'smooth'})}}><span>0{i+1}</span><b>{x}</b><ArrowRight size={16}/></button>)}</div></div></section></>}
 {view==='product'&&<section className="product-page"><button className="back-crumb" onClick={()=>go('store')}><ArrowLeft size={15}/> Course store <ChevronRight size={13}/> {book.category}</button><div className="product-main"><div className={`product-hero-cover ${book.cover}`}><span>CHESSBOARD PRESS <small>COURSE EDITION · 0{books.indexOf(book)+1}</small></span>{book.coverImage?(book.coverType?.startsWith('video/')?<video className="detail-media" src={book.coverImage} controls muted playsInline/>:<img className="detail-media" src={book.coverImage} alt={`${book.title} cover`}/>):<b>♞</b>}<i>{book.category.toUpperCase()}<br/><strong>{book.title.split(':')[0]}</strong></i></div><div className="product-overview"><div className="detail-tags">{book.category} <i/> {book.level} <i/> {book.duration}</div><h1>{book.title}</h1><div className="review-line">{book.reviews?`★ ${book.rating} · ${book.reviews.toLocaleString()} learner reviews`:`New course · No learner reviews yet`} <i/> By {book.author}</div><p>{book.description}</p><div className="product-learning"><b>What you’ll learn</b>{book.objectives.map(x=><span key={x}><Check size={15}/>{x}</span>)}</div><div className="purchase-box"><div><strong>${Number(book.price).toFixed(2)}</strong>{book.was&&<del>${Number(book.was).toFixed(2)}</del>}<small>Lifetime access · Digital course</small></div>{book.owned?<button className="blue-button" onClick={()=>startBook(book)}>Open in library <ArrowRight size={15}/></button>:<button className="blue-button" onClick={()=>addCart(book.id)}>Add to cart <ShoppingCart size={15}/></button>}<span><Shield size={14}/> Secure checkout · Instant access after payment</span></div></div></div><div className="product-tabs"><button className="selected">Course contents</button><button onClick={()=>setToast('Learner reviews are available after purchase')}>Reviews ({book.reviews||0})</button><button onClick={()=>setToast('Course details')}>About this course</button></div><div className="contents-layout"><section><h2>Inside the course</h2><p className="subtle-copy">{book.chapters} chapters · {book.lessons.length} lessons · Interactive chess book</p>{(book.chapterList?.length?book.chapterList:Array.from({length:Math.max(1,book.chapters||1)},(_,i)=>({title:['Introduction to the Vienna','Understanding the Vienna Gambit','Black’s Main Responses'][i]||`Chapter ${i+1}`,lessons:book.lessons[i]?[book.lessons[i]]:[]}))).map((ch,i)=><section className="book-chapter" key={`${ch.title}-${i}`}><div className="book-chapter-heading"><span>{String(i+1).padStart(2,'0')}</span><div><b>{ch.title}</b><small>{ch.lessons?.length||0} lessons</small></div><ChevronDown size={16}/></div>{ch.lessons?.map((l,j)=><div className="preview-lesson" key={`${l.title}-${j}`}><span>{String(j+1).padStart(2,'0')}</span><div><b>{l.title}</b><small>{l.moves?'Interactive chess line':'Lesson'} · Study at your pace</small></div></div>)}</section>)}</section><aside className="product-aside"><b>Course at a glance</b><span><BookOpen size={15}/> {book.chapters} chapters</span><span><GraduationCap size={15}/> {book.level} level</span><span><Clock3 size={15}/> {book.duration} of study</span><span><Trophy size={15}/> Exercises and review lines</span></aside></div></section>}
 {view==='cart'&&<section className="commerce-page"><div className="page-title"><small>YOUR CHECKOUT</small><h1>Shopping cart</h1></div><div className="cart-layout"><section className="cart-items">{cartBooks.length?cartBooks.map(b=><div className="cart-line" key={b.id}><div className={`cart-cover ${b.cover}`}>♞</div><div><b>{b.title}</b><small>{b.author} · Lifetime access</small><button onClick={()=>setCart(cart.filter(x=>x!==b.id))}>Remove</button></div><strong>${Number(b.price).toFixed(2)}</strong></div>):<div className="empty-cart"><ShoppingCart size={30}/><h2>Your cart is empty</h2><p>Find a course to begin building your chess library.</p><button className="blue-button" onClick={()=>go('store')}>Browse courses <ArrowRight size={15}/></button></div>}</section><aside className="cart-summary"><h3>Order summary</h3><div><span>Subtotal</span><b>${cartBooks.reduce((n,b)=>n+Number(b.price),0).toFixed(2)}</b></div><div><span>Discount code</span><span className="beta-coupon-note">Disabled in beta</span></div><hr/><div className="total"><b>Total</b><strong>${cartBooks.reduce((n,b)=>n+Number(b.price),0).toFixed(2)}</strong></div><button className="blue-button full" disabled={!cart.length} onClick={beginCheckout}>Continue to checkout <ArrowRight size={15}/></button><small><Shield size={13}/> {paymentsMode==='beta'?'Beta test checkout · no real charge':'Payment provider not configured'}</small></aside></div></section>}
